<div x-data="movieWizard()" class="space-y-6"><div class="flex justify-between"><div><h1 class="text-3xl font-bold">Películas</h1><p class="text-slate-400">Añadir y validar contenido desde bibliotecas autorizadas.</p></div><button @click="open=!open" class="bg-cyan-600 px-4 py-2 rounded">Añadir película</button></div>
<form x-show="open" x-cloak method="post" action="/movies" class="bg-slate-900 border border-slate-800 rounded-xl overflow-hidden"><?=$csrf->field()?><div class="grid grid-cols-4 bg-slate-800"><?php foreach(['Detalles','Información','Avanzado','Servidor'] as $n=>$label):?><button type="button" @click="tab=<?=$n+1?>" :class="tab===<?=$n+1?>?'bg-cyan-700':''" class="p-3"><?=$label?></button><?php endforeach?></div>
<section x-show="tab===1" class="p-6 grid md:grid-cols-3 gap-4"><label class="md:col-span-2">Nombre<input x-model="title" required name="title" class="w-full bg-slate-800 p-2 rounded mt-1"></label><label>Año<input x-model="year" type="number" name="year" class="w-full bg-slate-800 p-2 rounded mt-1"></label><label>Idioma TMDB<select x-model="language" name="tmdb_language" class="w-full bg-slate-800 p-2 rounded mt-1"><option>es-ES</option><option>en-US</option></select></label><button type="button" @click="searchTmdb" class="self-end bg-indigo-700 p-2 rounded">Buscar en TMDB</button><span x-text="tmdbError" class="text-red-400 self-end"></span><div class="md:col-span-3 grid md:grid-cols-3 gap-3"><template x-for="m in results" :key="m.id"><button type="button" @click="selectTmdb(m)" class="text-left border border-slate-700 rounded p-3"><strong x-text="m.title"></strong><div class="text-sm text-slate-400" x-text="(m.release_date||'').slice(0,4)"></div></button></template></div><input type="hidden" name="tmdb_id" :value="tmdbId"><label>Categoría<select name="category_id" class="w-full bg-slate-800 p-2 rounded mt-1"><option value="">Sin categoría</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>"><?=htmlspecialchars($c['name'])?></option><?php endforeach?></select></label><label class="md:col-span-2">Paquetes<select multiple name="package_ids[]" class="w-full bg-slate-800 p-2 rounded mt-1"><?php foreach($packages as $p):?><option value="<?=$p['id']?>"><?=htmlspecialchars($p['name'])?></option><?php endforeach?></select></label><button type="button" @click="tab=2" class="md:col-start-3 bg-cyan-700 p-2 rounded">Siguiente</button></section>
<section x-show="tab===2" class="p-6 grid md:grid-cols-2 gap-4"><label>Título original<input name="original_title" class="w-full bg-slate-800 p-2 rounded mt-1"></label><label>Póster URL<input x-model="poster" name="poster_url" class="w-full bg-slate-800 p-2 rounded mt-1"></label><label>Backdrop URL<input x-model="backdrop" name="backdrop_url" class="w-full bg-slate-800 p-2 rounded mt-1"></label><label>Director<input name="director" class="w-full bg-slate-800 p-2 rounded mt-1"></label><label class="md:col-span-2">Descripción<textarea x-model="plot" name="description" class="w-full h-28 bg-slate-800 p-2 rounded mt-1"></textarea></label><label>Reparto<input name="cast" class="w-full bg-slate-800 p-2 rounded mt-1"></label><label>Géneros<input name="genres" class="w-full bg-slate-800 p-2 rounded mt-1"></label><label>Tráiler YouTube<input name="trailer_url" class="w-full bg-slate-800 p-2 rounded mt-1"></label><label>Rating<input name="rating" class="w-full bg-slate-800 p-2 rounded mt-1"></label><label>País<input name="country" maxlength="2" class="w-full bg-slate-800 p-2 rounded mt-1"></label><label>Idioma<input name="language" class="w-full bg-slate-800 p-2 rounded mt-1"></label><div class="md:col-span-2 flex justify-between"><button type="button" @click="tab=1" class="bg-slate-700 px-4 py-2 rounded">Anterior</button><button type="button" @click="tab=3" class="bg-cyan-700 px-4 py-2 rounded">Siguiente</button></div></section>
<section x-show="tab===3" class="p-6 grid md:grid-cols-2 gap-4"><?php foreach(['direct_source'=>'Fuente directa','direct_stream'=>'Stream directo','native_frames'=>'Frames nativos','create_symlink'=>'Crear symlink','remove_subtitles'=>'Eliminar subtítulos','process_movie'=>'Procesar película'] as $name=>$label):?><label class="flex items-center justify-between bg-slate-800 p-3 rounded"><?=$label?><input type="checkbox" name="<?=$name?>" value="1"></label><?php endforeach?><label>Ruta de subtítulos<input name="subtitle_location" class="w-full bg-slate-800 p-2 rounded mt-1"></label><label>Perfil de transcodificación<input name="transcode_profile" placeholder="Desactivada" class="w-full bg-slate-800 p-2 rounded mt-1"></label><label>Contenedor<select name="target_container" class="w-full bg-slate-800 p-2 rounded mt-1"><option value="">Original</option><option>mp4</option><option>mkv</option><option>ts</option></select></label><div class="md:col-span-2 flex justify-between"><button type="button" @click="tab=2" class="bg-slate-700 px-4 py-2 rounded">Anterior</button><button type="button" @click="tab=4" class="bg-cyan-700 px-4 py-2 rounded">Siguiente</button></div></section>
<section x-show="tab===4" class="p-6 space-y-4"><label>Balanceador y biblioteca<select required name="library_id" class="w-full bg-slate-800 p-3 rounded mt-1"><option value="">Seleccionar</option><?php foreach($libraries as $l):?><option value="<?=$l['id']?>"><?=htmlspecialchars(($l['server_name']??'Servidor principal').' → '.$l['name'].' · '.$l['mount_path'].' · '.($l['server_status']??'local'))?></option><?php endforeach?></select></label><label>Ruta relativa del archivo<input required name="relative_path" placeholder="Movies/Película (2026).mkv" class="w-full bg-slate-800 p-3 rounded mt-1"><span class="text-xs text-slate-400">El agente comprobará que exista dentro de esta biblioteca.</span></label><div class="flex justify-between"><button type="button" @click="tab=3" class="bg-slate-700 px-4 py-2 rounded">Anterior</button><button class="bg-emerald-700 px-5 py-2 rounded">Añadir y validar</button></div></section></form>
<section class="grid md:grid-cols-2 xl:grid-cols-3 gap-4"><?php foreach($movies as $m):?><article class="bg-slate-900 border border-slate-800 rounded-xl p-4 flex gap-4"><?php if($m['poster_url']):?><img src="<?=htmlspecialchars($m['poster_url'])?>" class="w-20 h-28 object-cover rounded" alt=""><?php endif?><div><h2 class="font-bold"><?=htmlspecialchars($m['title'])?></h2><p class="text-sm text-slate-400"><?=htmlspecialchars((string)($m['release_year']??''))?> · <?=htmlspecialchars($m['server_name']??'Sin servidor')?></p><span class="text-xs <?=$m['file_status']==='available'?'text-emerald-400':'text-amber-400'?>"><?=htmlspecialchars($m['file_status']??$m['status'])?></span></div></article><?php endforeach?></section></div>
<script>function movieWizard(){return{open:false,tab:1,title:'',year:'',language:'es-ES',results:[],tmdbId:'',poster:'',backdrop:'',plot:'',tmdbError:'',searchTmdb(){this.tmdbError='';fetch('/movies/tmdb?'+new URLSearchParams({title:this.title,year:this.year,language:this.language})).then(r=>r.json()).then(r=>{if(!r.ok)throw new Error(r.error);this.results=r.data.results||[]}).catch(e=>this.tmdbError=e.message)},selectTmdb(m){this.tmdbId=m.id;this.title=m.title||this.title;this.year=(m.release_date||'').slice(0,4)||this.year;this.poster=m.poster_path?'https://image.tmdb.org/t/p/w500'+m.poster_path:'';this.backdrop=m.backdrop_path?'https://image.tmdb.org/t/p/original'+m.backdrop_path:'';this.plot=m.overview||'';this.results=[]}}}</script>
